INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "群臣上昭宗尊号，改元大顺", "start_year": 890, "end_year": 890, "time_original": "890年正月戊子朔", "dynasty": "唐", "description": "群臣上尊号圣文睿德光武弘孝皇帝，朝廷改元大顺。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "91f0fc11-656f-5b55-a0a7-352ff91ad314"}, {"title": "孟迁执王虔裕及汴兵降李克用", "start_year": 890, "end_year": 890, "time_original": "890年正月；具体日未载", "dynasty": "唐", "description": "李克用急攻邢州，孟迁粮尽力竭，拘执王虔裕及汴兵投降。", "phases": [], "location_name": "邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ac91b05b-0933-53a9-9214-343fcabb399b"}, {"title": "安金俊受任邢洺团练使", "start_year": 890, "end_year": 890, "time_original": "890年正月；孟迁降后", "dynasty": "唐", "description": "李克用以安金俊为邢洺团练使。", "phases": [], "location_name": "邢州、洺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7868f740-a146-5d81-ab49-a5aca6885460"}, {"title": "王建攻邛州，陈敬瑄遣杨儒助守", "start_year": 890, "end_year": 890, "time_original": "890年正月壬寅", "dynasty": "唐", "description": "王建进攻邛州，陈敬瑄遣大将杨儒率军帮助刺史毛湘守城，毛湘出战屡败。", "phases": [], "location_name": "邛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "75028b71-847e-5a7f-8a73-d6f0df23ed53"}, {"title": "杨儒降王建，被养为子赐名王宗儒", "start_year": 890, "end_year": 890, "time_original": "890年正月壬寅条；邛州战中", "dynasty": "唐", "description": "杨儒见王建军势盛，称唐祚将尽、王建治众严而不残，率部投降；王建收养其为子，改姓名为王宗儒。", "phases": [], "location_name": "邛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1f4c2f11-6ad7-5cbd-89ba-caa812ae3c05"}, {"title": "王建留张琳招安邛南，回兵成都", "start_year": 890, "end_year": 890, "time_original": "890年正月乙巳", "dynasty": "唐", "description": "王建留永平节度判官张琳为邛南招安使，率兵返回成都。《通鉴》称张琳为许州人。", "phases": [], "location_name": "邛南、成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "04c93493-3ba4-582b-9a3d-85d3686f8372"}, {"title": "陈敬瑄布寨征丁修守成都", "start_year": 890, "end_year": 890, "time_original": "890年正月条；具体日未载", "dynasty": "唐", "description": "陈敬瑄分兵在犀浦、郫、导江等县布寨，征城中民户一丁，白日开壕采竹木运砖石，夜间登城巡警，昼夜无休。", "phases": [], "location_name": "犀浦、郫、导江、成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1e4d1904-717a-53a8-9844-cb6075cd70dc"}, {"title": "韦昭度王建分别驻营唐桥东阊门外", "start_year": 890, "end_year": 890, "time_original": "890年正月；具体日未载", "dynasty": "唐", "description": "韦昭度驻营唐桥，王建驻营东阊门外；《通鉴》称王建事韦昭度甚谨。", "phases": [], "location_name": "唐桥、东阊门外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2af55cf0-69be-535f-8504-73960363c745"}, {"title": "杜有迁执员虔嵩降王建并知简州", "start_year": 890, "end_year": 890, "time_original": "890年正月辛亥", "dynasty": "唐", "description": "简州将杜有迁拘执刺史员虔嵩，投降王建；王建以杜有迁知州事。", "phases": [], "location_name": "简州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9e4f8b27-fca2-57b7-beec-92ba1cbd253f"}, {"title": "庞师古渡淮声称救杨行密，取天长", "start_year": 890, "end_year": 890, "time_original": "890年正月；具体日未载", "dynasty": "唐", "description": "庞师古等汴军渡淮，声称救援杨行密，攻取天长；其军号称十万。", "phases": [], "location_name": "淮、天长", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d2f39c0a-5049-5082-a45c-bb447d0c6c75"}, {"title": "庞师古攻取高邮", "start_year": 890, "end_year": 890, "time_original": "890年正月壬子", "dynasty": "唐", "description": "庞师古等汴军攻取高邮。", "phases": [], "location_name": "高邮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "eda5fb9a-ed1d-5707-b81d-4c5da4da28ed"}, {"title": "侯元绰执杨戡降王建并知资州", "start_year": 890, "end_year": 890, "time_original": "890年二月己未", "dynasty": "唐", "description": "资州将侯元绰拘执刺史杨戡，投降王建；王建以侯元绰知州事。", "phases": [], "location_name": "资州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1bd0ade1-05f8-5ca8-bf0b-895dac0cf7f1"}, {"title": "朱全忠加守中书令", "start_year": 890, "end_year": 890, "time_original": "890年二月乙丑", "dynasty": "唐", "description": "朝廷加朱全忠守中书令。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "094db0d1-e962-5f00-9178-0b0c7056318c"}, {"title": "庞师古败于孙儒退还", "start_year": 890, "end_year": 890, "time_original": "890年二月己巳", "dynasty": "唐", "description": "庞师古率兵深入淮南，在陵亭与孙儒交战，兵败后返回。", "phases": [], "location_name": "陵亭、淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0ce6d972-9fad-5523-ab9b-83ce8ad9b609"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

